import {
  buildFrontmatter,
  debug,
  DEBUG_PREFIX,
  extractFrontmatterFields,
  FRONTMATTER_REGEX,
  generateChapterId,
  generateDraftId,
  getDraftsFolderName,
  isValidChapterFrontmatter,
  MARKDOWN_FILE_EXTENSION,
  slugifyDraftName,
  suppressAsync,
} from "@/core/utils";
import type { WriteAidManager } from "@/manager";
import type { WriteAidSettings } from "@/types";
import { App, TFile, TFolder } from "obsidian";
import { updateMetaStats } from "./meta";

/**
 * Service for managing chapter files within drafts.
 * Handles creation, deletion, renaming, reordering, and listing of chapters.
 */
export class ChapterFileService {
  app: App;
  manager: WriteAidManager | null;

  constructor(app: App) {
    this.app = app;
    this.manager =
      (
        this.app as unknown as {
          plugins: { getPlugin?: (id: string) => { manager?: WriteAidManager } };
        }
      ).plugins.getPlugin?.("obsidian-writeaid-plugin")?.manager ?? null;
  }

  /**
   * Reorder chapters in a draft. Accepts an array of chapter objects in the new order.
   * Each object must have { chapterName, order }.
   */
  async reorderChapters(
    projectPath: string,
    draftName: string,
    newOrder: Array<{ name: string; chapterName: string; order: number }>,
  ) {
    debug(
      `${DEBUG_PREFIX} ChapterFileService.reorderChapters: starting reorder for ${projectPath}/${draftName}`,
    );
    debug(`${DEBUG_PREFIX} ChapterFileService.reorderChapters: newOrder:`, newOrder);
    const project = this.resolveProjectPath(projectPath);
    if (!project) {
      debug(`${DEBUG_PREFIX} ChapterFileService.reorderChapters: no project resolved`);
      return false;
    }
    const draftsFolderName = this.getDraftsFolderName();
    if (!draftsFolderName) {
      debug(`${DEBUG_PREFIX} ChapterFileService.reorderChapters: no drafts folder found`);
      return false;
    }
    const draftFolder = `${project}/${draftsFolderName}/${draftName}`;
    debug(`${DEBUG_PREFIX} ChapterFileService.reorderChapters: draftFolder=${draftFolder}`);
    for (let i = 0; i < newOrder.length; i++) {
      const { name } = newOrder[i];
      const filePath = `${draftFolder}/${name}${MARKDOWN_FILE_EXTENSION}`;
      debug(`${DEBUG_PREFIX} ChapterFileService.reorderChapters: processing file ${filePath}`);
      const file = this.app.vault.getAbstractFileByPath(filePath);
      debug(`${DEBUG_PREFIX} ChapterFileService.reorderChapters: file found:`, !!file);
      if (file && file instanceof TFile) {
        let content = await this.app.vault.read(file);
        debug(
          `${DEBUG_PREFIX} ChapterFileService.reorderChapters: read content, length=${content.length}`,
        );
        if (content.match(FRONTMATTER_REGEX)) {
          debug(
            `${DEBUG_PREFIX} ChapterFileService.reorderChapters: updating order from current to ${i + 1}`,
          );
          content = content.replace(FRONTMATTER_REGEX, (match, fm) => {
            const fields = extractFrontmatterFields(fm);
            fields.order = i + 1;
            return buildFrontmatter(fields);
          });
          debug(`${DEBUG_PREFIX} ChapterFileService.reorderChapters: modifying file`);
          await this.app.vault.modify(file, content);
          debug(`${DEBUG_PREFIX} ChapterFileService.reorderChapters: file modified`);
        }
      }
    }
    debug(`${DEBUG_PREFIX} ChapterFileService.reorderChapters: reorder complete`);
    return true;
  }

  /**
   * List chapters for a draft in a multi-file project. Returns array of { name, chapterName? }
   */
  async listChapters(
    projectPath: string,
    draftName: string,
  ): Promise<Array<{ name: string; chapterName?: string }>> {
    debug(
      `${DEBUG_PREFIX} ChapterFileService.listChapters: projectPath=${projectPath}, draftName=${draftName}`,
    );
    const project = this.resolveProjectPath(projectPath);
    if (!project) {
      debug(`${DEBUG_PREFIX} ChapterFileService.listChapters: no project resolved`);
      return [];
    }
    // Find the drafts folder, case-insensitively
    const draftsFolderName = this.getDraftsFolderName();
    if (!draftsFolderName) {
      debug(
        `${DEBUG_PREFIX} ChapterFileService.listChapters: no drafts folder found in project ${project}`,
      );
      return [];
    }
    const draftFolder = `${project}/${draftsFolderName}/${draftName}`;
    debug(
      `${DEBUG_PREFIX} ChapterFileService.listChapters: resolved project=${project}, draftsFolder=${draftsFolderName}, draftFolder=${draftFolder}`,
    );
    const folder = this.app.vault.getAbstractFileByPath(draftFolder);
    const chapters: Array<{ name: string; chapterName?: string; order: number }> = [];
    if (folder && folder instanceof TFolder) {
      debug(
        `${DEBUG_PREFIX} ChapterFileService.listChapters: found folder with ${folder.children.length} children`,
      );
      for (const file of folder.children) {
        if (file instanceof TFile && file.extension === MARKDOWN_FILE_EXTENSION.slice(1)) {
          debug(`${DEBUG_PREFIX} ChapterFileService.listChapters: processing file ${file.path}`);
          await suppressAsync(async () => {
            const content = await this.app.vault.read(file);
            debug(
              `${DEBUG_PREFIX} ChapterFileService.listChapters: content length ${content.length}`,
            );

            // Check if this is a valid chapter (has all required fields as specified in REQUIRED_CHAPTER_FIELDS)
            if (!this.isValidChapter(content)) {
              debug(
                `${DEBUG_PREFIX} ChapterFileService.listChapters: ${file.path} is not a valid chapter (missing required fields)`,
              );
              return;
            }

            const fmMatch = content.match(FRONTMATTER_REGEX);
            let order: number | undefined = undefined;
            let chapterName: string | undefined = undefined;
            if (fmMatch) {
              debug(`${DEBUG_PREFIX} ChapterFileService.listChapters: found frontmatter`);
              const lines = fmMatch[1].split(/\r?\n/);
              for (const line of lines) {
                const mOrder = line.match(/^order:\s*(\d+)/i);
                if (mOrder) order = parseInt(mOrder[1], 10);
                const mChapterName = line.match(/^chapter_name:\s*(.*)$/i);
                if (mChapterName) {
                  let val = mChapterName[1].trim();
                  if (
                    (val.startsWith('"') && val.endsWith('"')) ||
                    (val.startsWith("'") && val.endsWith("'"))
                  ) {
                    val = val.slice(1, -1);
                  }
                  if (val.length > 0) chapterName = val;
                }
              }
            } else {
              debug(`${DEBUG_PREFIX} ChapterFileService.listChapters: no frontmatter`);
            }
            debug(
              `${DEBUG_PREFIX} ChapterFileService.listChapters: parsed order=${order}, chapterName=${chapterName}`,
            );
            const chapName =
              chapterName && chapterName.length > 0
                ? chapterName
                : file.name.replace(new RegExp(`\\${MARKDOWN_FILE_EXTENSION}$`), "");
            const chapOrder = typeof order === "number" && !isNaN(order) ? order : 0;
            debug(
              `${DEBUG_PREFIX} ChapterFileService.listChapters: adding chapter ${file.name} with name ${chapName}, order ${chapOrder}`,
            );
            chapters.push({
              name: file.name.replace(new RegExp(`\\${MARKDOWN_FILE_EXTENSION}$`), ""),
              chapterName: chapName,
              order: chapOrder,
            });
          });
        }
      }
    } else {
      debug(`${DEBUG_PREFIX} ChapterFileService.listChapters: no folder found`);
    }
    chapters.sort((a, b) => a.order - b.order);
    debug(`${DEBUG_PREFIX} ChapterFileService.listChapters: returning ${chapters.length} chapters`);
    return chapters.map(({ name, chapterName }) => ({ name, chapterName }));
  }

  /** Create a new chapter file in a draft folder. */
  async createChapter(
    projectPath: string,
    draftName: string,
    chapterName: string,
    settings?: WriteAidSettings,
    draftId?: string,
  ) {
    debug(
      `${DEBUG_PREFIX} createChapter called: chapterName=${chapterName}, draft=${draftName}, draftId=${draftId}`,
    );
    const project = this.resolveProjectPath(projectPath);
    if (!project) {
      debug(`${DEBUG_PREFIX} createChapter: no project resolved`);
      return false;
    }
    // Find the drafts folder, case-insensitively
    const draftsFolderName = this.getDraftsFolderName();
    if (!draftsFolderName) {
      debug(`${DEBUG_PREFIX} createChapter: no drafts folder found`);
      return false;
    }
    const draftFolder = `${project}/${draftsFolderName}/${draftName}`;
    const slug = slugifyDraftName(
      chapterName,
      settings?.slugStyle as import("@/core/utils").DraftSlugStyle,
    );
    const fileName = `${slug}${MARKDOWN_FILE_EXTENSION}`;
    const filePath = `${draftFolder}/${fileName}`;
    if (this.app.vault.getAbstractFileByPath(filePath)) {
      debug(`${DEBUG_PREFIX} createChapter: file already exists at ${filePath}`);
      return false;
    }
    let maxOrder = 0;
    let existingDraftId: string | null = null;
    const folder = this.app.vault.getAbstractFileByPath(draftFolder);
    if (folder && folder instanceof TFolder) {
      for (const file of folder.children) {
        if (file instanceof TFile && file.extension === MARKDOWN_FILE_EXTENSION.slice(1)) {
          await suppressAsync(async () => {
            const content = await this.app.vault.read(file);
            // Only count order from valid chapters
            if (this.isValidChapter(content)) {
              const fmMatch = content.match(FRONTMATTER_REGEX);
              if (fmMatch) {
                const lines = fmMatch[1].split(/\r?\n/);
                for (const line of lines) {
                  const m = line.match(/^order:\s*(\d+)/i);
                  if (m) {
                    const ord = parseInt(m[1], 10);
                    if (!isNaN(ord) && ord > maxOrder) maxOrder = ord;
                  }
                  // Extract draft ID from the first valid chapter found
                  if (!existingDraftId) {
                    const idMatch = line.match(/^id:\s*(.+)/i);
                    if (idMatch) {
                      existingDraftId = idMatch[1].trim();
                    }
                  }
                }
              }
            }
          });
        }
      }
    }
    const order = maxOrder + 1;
    let title = `# ${chapterName}`;
    // Create frontmatter with all 6 documented fields:
    //   chapter_id: Unique identifier for this chapter
    //   order: The chapter's order within the draft
    //   chapter_name: The name/title of the chapter
    //   draft_id: Identifier for the draft this chapter belongs to
    //   word_count: Number of words in the chapter (initialized to 0)
    //   last_updated: ISO timestamp of when the chapter was created/updated
    // If draftId is not provided, try to use existing draft ID from other chapters
    // Otherwise, generate a new one
    const finalDraftId = draftId || existingDraftId || generateDraftId();
    const now = new Date().toISOString();
    const chapterId = generateChapterId();
    const frontmatter = buildFrontmatter({
      chapter_id: chapterId,
      order: order,
      chapter_name: chapterName,
      draft_id: finalDraftId,
      word_count: 0,
      last_updated: now,
    });
    await this.app.vault.create(filePath, `${frontmatter}${title}\n\n`);
    debug(`${DEBUG_PREFIX} createChapter: created chapter file`, {
      filePath,
      order,
      chapter_name: chapterName,
      chapter_id: chapterId,
      draft_id: finalDraftId,
      word_count: 0,
      last_updated: now,
    });

    // Update metadata to recalculate total_chapters
    await suppressAsync(async () => {
      await updateMetaStats(this.app, project, draftName, undefined, settings);
    });

    return true;
  }

  /** Delete a chapter file from a draft folder. */
  async deleteChapter(
    projectPath: string,
    draftName: string,
    chapterName: string,
    settings?: WriteAidSettings,
  ) {
    debug(`${DEBUG_PREFIX} deleteChapter called: chapterName=${chapterName}, draft=${draftName}`);
    const project = this.resolveProjectPath(projectPath);
    if (!project) {
      debug(`${DEBUG_PREFIX} deleteChapter: no project resolved`);
      return false;
    }
    // Find the drafts folder, case-insensitively
    const draftsFolderName = this.getDraftsFolderName();
    if (!draftsFolderName) {
      debug(`${DEBUG_PREFIX} deleteChapter: no drafts folder found`);
      return false;
    }
    const draftFolder = `${project}/${draftsFolderName}/${draftName}`;
    const fileName = `${chapterName}${MARKDOWN_FILE_EXTENSION}`;
    const filePath = `${draftFolder}/${fileName}`;
    const file = this.app.vault.getAbstractFileByPath(filePath);
    if (file && file instanceof TFile) {
      await this.app.vault.delete(file);
      // After deletion, reassign order for all remaining chapters using listChapters
      const chapters = await this.listChapters(projectPath, draftName);
      for (let i = 0; i < chapters.length; i++) {
        const { name } = chapters[i];
        const chapterFilePath = `${draftFolder}/${name}${MARKDOWN_FILE_EXTENSION}`;
        const chapterFile = this.app.vault.getAbstractFileByPath(chapterFilePath);
        if (chapterFile && chapterFile instanceof TFile) {
          let content = await this.app.vault.read(chapterFile);
          if (content.match(FRONTMATTER_REGEX)) {
            content = content.replace(FRONTMATTER_REGEX, (match, fm) => {
              const fields = extractFrontmatterFields(fm);
              fields.order = i + 1;
              return buildFrontmatter(fields);
            });
            await this.app.vault.modify(chapterFile, content);
          }
        }
      }

      // Update metadata to recalculate total_chapters
      await suppressAsync(async () => {
        await updateMetaStats(this.app, project, draftName, undefined, settings);
      });

      return true;
    }
    return false;
  }

  /** Rename a chapter file and/or update its short name. */
  async renameChapter(projectPath: string, draftName: string, oldName: string, newName: string) {
    debug(`${DEBUG_PREFIX} renameChapter called: ${oldName} -> ${newName}`);
    const project = this.resolveProjectPath(projectPath);
    if (!project) {
      debug(`${DEBUG_PREFIX} renameChapter: no project resolved`);
      return false;
    }
    // Find the drafts folder, case-insensitively
    const draftsFolderName = this.getDraftsFolderName();
    if (!draftsFolderName) {
      debug(`${DEBUG_PREFIX} renameChapter: no drafts folder found`);
      return false;
    }
    const draftFolder = `${project}/${draftsFolderName}/${draftName}`;
    const oldFile = `${draftFolder}/${oldName}${MARKDOWN_FILE_EXTENSION}`;
    const newFile = `${draftFolder}/${newName}${MARKDOWN_FILE_EXTENSION}`;
    const file = this.app.vault.getAbstractFileByPath(oldFile);
    if (!file || !(file instanceof TFile)) {
      debug(`${DEBUG_PREFIX} renameChapter: file not found at ${oldFile}`);
      return false;
    }
    let content = await this.app.vault.read(file);
    let title = `# ${newName}`;

    if (content.match(FRONTMATTER_REGEX)) {
      content = content.replace(FRONTMATTER_REGEX, (match, fm) => {
        const fields = extractFrontmatterFields(fm);
        fields.chapter_name = newName;
        return buildFrontmatter(fields);
      });
    }
    content = content.replace(/^#.*$/m, title);
    if (oldName !== newName) {
      await this.app.vault.create(newFile, content);
      await this.app.vault.delete(file);
    } else {
      await this.app.vault.modify(file, content);
    }
    return true;
  }

  /**
   * Open a chapter file in Obsidian.
   * @param projectPath The project path
   * @param draftName The draft name
   * @param chapterName The chapter name
   * @returns true if the file was opened successfully
   */
  async openChapter(
    projectPath: string | undefined,
    draftName: string,
    chapterName: string,
  ): Promise<boolean> {
    const project = this.resolveProjectPath(projectPath);
    if (!project) return false;
    const draftsFolderName = this.getDraftsFolderName();
    if (!draftsFolderName) return false;
    const filePath = `${project}/${draftsFolderName}/${draftName}/${chapterName}${MARKDOWN_FILE_EXTENSION}`;
    const file = this.app.vault.getAbstractFileByPath(filePath);
    if (file && file instanceof TFile) {
      await suppressAsync(async () => {
        const leaf = this.app.workspace.getLeaf();
        await leaf.openFile(file);
      });
      return true;
    }
    return false;
  }

  private resolveProjectPath(projectPath?: string): string | null {
    return projectPath || this.manager?.activeProject || null;
  }

  private getDraftsFolderName(): string {
    // Return the configured drafts folder name without legacy checks
    return getDraftsFolderName(this.manager?.settings);
  }

  /**
   * Check if a chapter file has all required frontmatter fields
   * @param frontmatter The frontmatter content (without delimiters)
   * @returns true if the chapter has all required fields
   */
  private hasRequiredChapterFields(frontmatter: string): boolean {
    return isValidChapterFrontmatter(frontmatter);
  }

  /**
   * Extract chapter metadata from frontmatter
   * @param frontmatter The frontmatter content (without delimiters)
   * @returns Object with all required chapter fields or null if missing required fields
   */
  private extractChapterMetadata(frontmatter: string): {
    chapterId?: string;
    order?: number;
    chapterName?: string;
    draftId?: string;
    wordCount?: number;
    lastUpdated?: string;
  } | null {
    if (!this.hasRequiredChapterFields(frontmatter)) {
      return null;
    }

    let chapterId: string | undefined;
    let order: number | undefined;
    let chapterName: string | undefined;
    let draftId: string | undefined;
    let wordCount: number | undefined;
    let lastUpdated: string | undefined;

    const lines = frontmatter.split(/\r?\n/);
    for (const line of lines) {
      const chapterIdMatch = line.match(/^chapter_id:\s*(.+?)$/i);
      if (chapterIdMatch) chapterId = chapterIdMatch[1].trim();

      const orderMatch = line.match(/^order:\s*(\d+)/i);
      if (orderMatch) order = parseInt(orderMatch[1], 10);

      const nameMatch = line.match(/^chapter_name:\s*(.*)$/i);
      if (nameMatch) {
        let val = nameMatch[1].trim();
        if (
          (val.startsWith('"') && val.endsWith('"')) ||
          (val.startsWith("'") && val.endsWith("'"))
        ) {
          val = val.slice(1, -1);
        }
        if (val.length > 0) chapterName = val;
      }

      const draftIdMatch = line.match(/^draft_id:\s*(.+?)$/i);
      if (draftIdMatch) draftId = draftIdMatch[1].trim();

      const wordCountMatch = line.match(/^word_count:\s*(\d+)/i);
      if (wordCountMatch) wordCount = parseInt(wordCountMatch[1], 10);

      const lastUpdatedMatch = line.match(/^last_updated:\s*(.+?)$/i);
      if (lastUpdatedMatch) lastUpdated = lastUpdatedMatch[1].trim();
    }

    return { chapterId, order, chapterName, draftId, wordCount, lastUpdated };
  }

  /**
   * Check if a file is a valid chapter (has all required frontmatter fields)
   * Uses isValidChapterFrontmatter for validation of required fields.
   */
  isValidChapter(content: string): boolean {
    const fmMatch = content.match(FRONTMATTER_REGEX);
    if (!fmMatch) return false;
    return this.hasRequiredChapterFields(fmMatch[1]);
  }

  /**
   * Update the last_updated timestamp on a chapter file
   * @param projectPath - Project root path
   * @param draftName - Draft folder name
   * @param chapterName - Chapter file name (without extension)
   * @param wordCount - Optional word count to update
   */
  async updateChapterLastUpdated(
    projectPath: string,
    draftName: string,
    chapterName: string,
    wordCount?: number,
  ): Promise<boolean> {
    debug(`${DEBUG_PREFIX} updateChapterLastUpdated called for ${chapterName} in ${draftName}`);
    const project = this.resolveProjectPath(projectPath);
    if (!project) {
      debug(`${DEBUG_PREFIX} updateChapterLastUpdated: no project resolved`);
      return false;
    }

    const draftsFolderName = this.getDraftsFolderName();
    if (!draftsFolderName) {
      debug(`${DEBUG_PREFIX} updateChapterLastUpdated: no drafts folder found`);
      return false;
    }

    const draftFolder = `${project}/${draftsFolderName}/${draftName}`;
    const filePath = `${draftFolder}/${chapterName}${MARKDOWN_FILE_EXTENSION}`;

    // Delegate to updateChapterMetadata to avoid code duplication
    return this.updateChapterMetadata(filePath, wordCount);
  }

  /**
   * Update chapter metadata (word count and last_updated) for a chapter file
   * @param filePath - Full file path to the chapter
   * @param wordCount - Optional new word count
   */
  async updateChapterMetadata(filePath: string, wordCount?: number): Promise<boolean> {
    debug(`${DEBUG_PREFIX} updateChapterMetadata called for ${filePath}`);

    const file = this.app.vault.getAbstractFileByPath(filePath);
    if (!file || !(file instanceof TFile)) {
      debug(`${DEBUG_PREFIX} updateChapterMetadata: file not found at ${filePath}`);
      return false;
    }

    try {
      const content = await this.app.vault.read(file);
      const fmMatch = content.match(FRONTMATTER_REGEX);

      if (!fmMatch) {
        debug(`${DEBUG_PREFIX} updateChapterMetadata: no frontmatter found`);
        return false;
      }

      const fields = extractFrontmatterFields(fmMatch[1]);
      const now = new Date().toISOString();

      // Always update last_updated
      fields.last_updated = now;

      // Update word count if provided
      if (wordCount !== undefined) {
        fields.word_count = wordCount;
      }

      const body = content.substring(fmMatch[0].length);
      const updatedContent = `${buildFrontmatter(fields)}${body}`;

      await this.app.vault.modify(file, updatedContent);
      debug(
        `${DEBUG_PREFIX} updateChapterMetadata: updated ${filePath} with last_updated ${now}${
          wordCount !== undefined ? ` and word_count ${wordCount}` : ""
        }`,
      );
      return true;
    } catch (error) {
      debug(`${DEBUG_PREFIX} updateChapterMetadata error:`, error);
      return false;
    }
  }
}
